CREATE COLUMN TABLE "TEST_AP"."OBOI" ("AbsEntry" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(15) NOT NULL , "Name" NVARCHAR(100), "QueryId" INTEGER CS_INT, "QCategory" INTEGER CS_INT, "Desc" NVARCHAR(200), "MenuId" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBOI_CODE" ON "TEST_AP"."OBOI" ( "Code" ASC )